function getLatteLabel(category) {
  if (category === "焙茶") return "焙茶拿鐵";
  if (category === "玄米茶") return "玄米茶拿鐵";
  return "抹茶拿鐵";
}
function getOccasions(category) {
  return [getLatteLabel(category), "純飲", "烘焙", "入饌", "其他"];
}

