const RATING_FILL = { 1: "#D7E8D2", 2: "#BDDBBD", 3: "#8DC48D", 4: "#4F9A6F", 5: "#2B7056" };

const DATE_RE = /^(\d{4})\/(\d{2})\/(\d{2})$/;
function parseDMY(s) {
  if (!s) return null;
  const m = DATE_RE.exec(s.trim());
  if (!m) return null;
  const [, y, mo, d] = m;
  const dt = new Date(Number(y), Number(mo) - 1, Number(d));
  if (isNaN(dt.getTime())) return null;
  return dt;
}
function todayDMY() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}/${pad(d.getMonth() + 1)}/${pad(d.getDate())}`;
}
function currentTimeHHMM() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `${pad(d.getHours())}:${pad(d.getMinutes())}`;
}
function formatDMYInput(value) {
  const digits = value.replace(/\D/g, "").slice(0, 8);
  if (digits.length > 6) return `${digits.slice(0, 4)}/${digits.slice(4, 6)}/${digits.slice(6)}`;
  if (digits.length > 4) return `${digits.slice(0, 4)}/${digits.slice(4)}`;
  return digits;
}
function DateInput({ value, onChange, className = "", small = false, hideIcon = false, ...rest }) {
  const m = /^(\d{4})\/(\d{2})\/(\d{2})$/.exec(value || "");
  const iso = m ? `${m[1]}-${m[2]}-${m[3]}` : "";
  const hasWidth = /(^|\s)w-/.test(className);
  return (
    <div className="flex items-center gap-1 min-w-0">
      {small ? (
        // real font-size stays 16px (prevents iOS focus-zoom); scaled down so it looks like 15px
        <div className="flex-1 min-w-0">
          <input value={value} onChange={onChange} className={`${className} block`}
            style={{ fontSize: 16, transform: "scale(0.9375)", transformOrigin: "left center", width: "106.667%", maxWidth: "none" }} {...rest} />
        </div>
      ) : (
        <input value={value} onChange={onChange} className={`${className} min-w-0 ${hasWidth ? "" : "flex-1"}`} {...rest} />
      )}
      {!hideIcon && <label className="relative shrink-0 w-8 h-8 flex items-center justify-center text-[#6B6558] cursor-pointer">
        <RowIcon name="calendar" size={18} />
        <input type="date" value={iso} aria-label="date"
          onClick={(e) => { try { if (e.currentTarget.showPicker) e.currentTarget.showPicker(); } catch (err) { /* ignore */ } }}
          onChange={(e) => { const v = e.target.value; if (v) onChange({ target: { value: v.replace(/-/g, "/") } }); }}
          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
      </label>}
    </div>
  );
}
function daysFromToday(target) {
  const start = new Date();
  start.setHours(0, 0, 0, 0);
  const t = new Date(target);
  t.setHours(0, 0, 0, 0);
  return Math.round((t - start) / 86400000);
}

